#!/bin/bash
# Generates Secrets.xcconfig from .env so the key never lives in a tracked file.
# Run after cloning, or whenever the key changes:  ./Scripts/make-secrets.sh
set -euo pipefail
cd "$(dirname "$0")/.."

[ -f .env ] || { echo "No .env found. Copy .env.example and fill it in."; exit 1; }
set -a && . ./.env && set +a
: "${AI_GATEWAY_API_KEY:?AI_GATEWAY_API_KEY missing from .env}"

cat > Secrets.xcconfig <<XCCONFIG
// Generated by Scripts/make-secrets.sh — do not edit, do not commit.
AI_GATEWAY_API_KEY = ${AI_GATEWAY_API_KEY}
XCCONFIG

chmod 600 Secrets.xcconfig
echo "Wrote Secrets.xcconfig (key ending ...${AI_GATEWAY_API_KEY: -4})"
